from typing import List

class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        counts = {}
        n = len(nums)

        # Iterate over all subarrays of size k
        for i in range(n - k + 1):
            # Create a set of the current subarray to handle duplicates within the subarray
            sub_set = set(nums[i : i+k])
            # Count how many subarrays contain each number
            for x in sub_set:
                counts[x] = counts.get(x, 0) + 1

        # Find the largest integer that appears in exactly one subarray
        result = -1
        for x, count in counts.items():
            if count == 1:
                if x > result:
                    result = x

        return result
