class Solution:
    def maxDifference(self, s: str) -> int:
        # Dictionary to store frequency of each character
        counts = {}
        for char in s:
            counts[char] = counts.get(char, 0) + 1

        # Initialize variables to track the maximum odd frequency and minimum even frequency
        max_odd_freq = -1
        min_even_freq = float('inf')

        # Iterate through the frequencies
        for count in counts.values():
            if count % 2 == 1:
                # If frequency is odd, update max_odd_freq
                max_odd_freq = max(max_odd_freq, count)
            else:
                # If frequency is even, update min_even_freq
                min_even_freq = min(min_even_freq, count)

        # The maximum difference is the highest odd frequency minus the lowest even frequency
        return max_odd_freq - min_even_freq
