from typing import List

class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total_sum = 0
        n = len(nums)

        for i in range(n):
            is_good = True

            # Check if nums[i] is strictly greater than nums[i - k]
            # If i - k is a valid index, we must check the condition
            if i - k >= 0:
                if nums[i] <= nums[i - k]:
                    is_good = False

            # Check if nums[i] is strictly greater than nums[i + k]
            # If i + k is a valid index, we must check the condition
            if i + k < n:
                if nums[i] <= nums[i + k]:
                    is_good = False

            # If nums[i] is strictly greater than all valid neighbors at distance k
            if is_good:
                total_sum += nums[i]

        return total_sum
