class Solution:
    def maxDifference(self, s: str) -> int:
        # Dictionary to store the frequency of each character
        freq = {}
        for char in s:
            freq[char] = freq.get(char, 0) + 1

        # Initialize variables to track the maximum odd frequency and minimum even frequency
        # Since frequencies are at least 1, initializing max_odd to 0 is safe.
        # min_even should be initialized to a value larger than any possible frequency.
        # The maximum length is 100, so 101 is sufficient, or float('inf').
        max_odd = 0
        min_even = float('inf')

        # Iterate through the frequencies of the characters found
        for count in freq.values():
            # If the frequency is odd, update the maximum odd frequency found so far
            if count % 2 == 1:
                if count > max_odd:
                    max_odd = count
            # If the frequency is even, update the minimum even frequency found so far
            else:
                if count < min_even:
                    min_even = count

        # The problem asks to maximize (odd_frequency - even_frequency)
        # We found the maximum odd_frequency and minimum even_frequency.
        return max_odd - min_even
