from typing import List

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        parent = list(range(n))

        def find(i):
            if parent[i] != i:
                parent[i] = find(parent[i])
            return parent[i]

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j

        # Precompute sets for faster intersection
        sets = [set(row) for row in properties]

        for i in range(n):
            for j in range(i + 1, n):
                # Check if intersection size is at least k
                if len(sets[i] & sets[j]) >= k:
                    union(i, j)

        # Count the number of unique roots
        components = 0
        for i in range(n):
            if parent[i] == i:
                components += 1

        return components
